    "implementation_confidence": 75,
    "acceptance_evidence_sufficiency": {
      "reported": "insufficient now",
      "basis": "The final response cited C13-R3 failing to resolve the ticket-source concern, absence of runtime/integration evidence, and other agreed constraints not covered by the retrieved evidence."
